  manual=take.startswith(('bendtime-viewer','native-','outofmana-hand-fx')); passed=result.get('passed', result.get('failure') is None)
  info=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','stream=avg_frame_rate','-of','json',str(video)],text=True)); n,d=map(float,info['streams'][0]['avg_frame_rate'].split('/'))
  failure=take.startswith(('outofmana-', 'failure-fx-')) or 'no-mana' in take
  req=['corvo_bend_time_cast_end']+(['power_interruptions_and_no_mana']if failure or 'resume' in take or 'pause' in take or 'stop' in take else [])
  row=dict(video=video.name,character='corvo',label='Bend Time · '+take.replace('bendtime-','')+(' · source'if suffix else'')+(' · failed check'if not passed else''),alias='native_out_of_mana_standing_armed'if failure else'native_phase_bend_time_in',requirements=req,gameplay_bound=not manual and not suffix,complete=False,visual_accepted=False,evidence=take+'/result.json',visual_review=take+'/visual-review.json'if inspected else None,proxy_sha256=result['dll'],bank_sha256=result.get('bankSha256'),actual_capture_hz=n/d,video_sha256=hashlib.sha256(video.read_bytes()).hexdigest().upper(),checks_passed=passed,scope=result['scope'])
  if take.startswith('outofmana-hand-fx'):
   row['character']='emily' if 'emily' in take else 'corvo';row['requirements']=['power_interruptions_and_no_mana'];row['label']='Native failure hand FX · '+row['character']+' · manual'
  videos=[v for v in videos if v['video']!=video.name]; videos.append(row); evidence[video.name]=row
